{
  "summary": "Added a location enum quality tracking the crew's position: street, lobby, or vault. It is extractor-sourced and read as a choice, since the prose will plainly state where the crew is.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "crew_location",
        "type": "enum",
        "source": "extractor",
        "values": ["street", "lobby", "vault"],
        "rubric": "Where is the crew right now? Answer street if they are outside the bank, lobby if they are inside the public area, vault if they are in or at the vault room.",
        "read_as": "choice"
      }
    }
  ]
}

{
  "summary": "Declared the core dramatic-state qualities for the story: a latching boolean for the protagonist's commitment, a monotonic trust meter, a rising danger level, a latching enum for the central relationship stance, and a code-driven chance roll for a recurring hazard. These give the extractor concrete, prose-visible questions to answer each turn and give gates something to test.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "protagonist_committed",
        "type": "bool",
        "source": "extractor",
        "rubric": "Has the protagonist openly committed to the central goal (spoken aloud or taken an irreversible action toward it)? true only when the prose shows the commitment, not merely a wish.",
        "latching": true,
        "read_as": "choice"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "ally_trust",
        "type": "int",
        "source": "extractor",
        "rubric": "How much does the key ally trust the protagonist right now? 0 = openly hostile or refusing to cooperate, 5 = would risk their life for the protagonist. Rate from what the ally says and does in the prose.",
        "monotonic": true,
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "danger_level",
        "type": "int",
        "source": "extractor",
        "rubric": "How immediate is the physical threat to the protagonist in this scene? 0 = safe and unobserved, 5 = in immediate mortal danger. Rate from what is shown on the page.",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "relationship_stance",
        "type": "enum",
        "source": "extractor",
        "rubric": "What is the key ally's current stance toward the protagonist? Answer 'ally' if they are actively helping, 'wary' if they cooperate but keep distance, 'hostile' if they oppose or threaten the protagonist.",
        "values": ["ally", "wary", "hostile"],
        "latching": true,
        "read_as": "choice"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "hazard_strikes",
        "type": "bool",
        "source": "code",
        "rubric": "Seeded chance roll: true when the recurring hazard catches the protagonist off guard this beat.",
        "roll": { "sides": 6, "target": 2 }
      }
    }
  ]
}

{
