  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "committed_to_journey",
        "type": "bool",
        "source": "extractor",
        "read_as": "choice",
        "latching": true,
        "rubric": "Has the protagonist explicitly agreed to undertake the journey? true only when they say yes aloud or clearly accept the task in dialogue."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "ally_trust",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "monotonic": true,
        "rubric": "from 1 (barely) to 5 (completely): How much does the companion trust the protagonist, judging by what they say and do in the scene?"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "danger_level",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (barely) to 5 (completely): How dangerous does the current situation appear, judging by threats shown or described in the prose?"
